selector_to_html = {"a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><h2>Software requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2><p>The required runtime stack depends on the selected vendor, framework, and image. Use the centralized vendor/framework/image-selection page for platform-specific SDKs, framework builds, images, validation status, and package versions: <a class=\"reference external\" href=\"https://flagos.io/resourcedownload?lang=en\">centralized vendor/framework/image-selection page</a>.</p><p>Generic requirements for sglang-plugin-FL are:</p>", "a[href=\"#getting-started\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">#</a></h1><p>This section covers the requirements for installing sglang-plugin-FL and guides you through the installation process and running an inference task.</p>", "a[href=\"quick-run-inference-task.html#installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">#</a></h2><h3>1. Install SGLang v0.5.11<a class=\"headerlink\" href=\"#install-sglang-v0-5-11\" title=\"Link to this heading\">#</a></h3>", "a[href=\"quick-run-inference-task.html#download-models\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Download models<a class=\"headerlink\" href=\"#download-models\" title=\"Link to this heading\">#</a></h2><p>If HuggingFace is not accessible, use a mirror:</p>", "a[href=\"install.html#runtime-images-and-platform-packages\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Runtime images and platform packages<a class=\"headerlink\" href=\"#runtime-images-and-platform-packages\" title=\"Link to this heading\">#</a></h2><p>Vendor-specific framework selection, runtime images, validation status, installation commands, and adaptation procedures are maintained on the centralized page: <a class=\"reference external\" href=\"https://flagos.io/resourcedownload?lang=en\">centralized vendor/framework/image-selection page</a>. Use that page to choose the vendor, framework, and image before installing or launching sglang-plugin-FL.</p><p>This page intentionally does not maintain a full image matrix or platform-specific package recipe.</p>", "a[href=\"quick-run-inference-task.html#run-the-inference-task\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Run the inference task<a class=\"headerlink\" href=\"#run-the-inference-task\" title=\"Link to this heading\">#</a></h2><h3>1. Launch sglang server<a class=\"headerlink\" href=\"#launch-sglang-server\" title=\"Link to this heading\">#</a></h3><h4>Single GPU<a class=\"headerlink\" href=\"#single-gpu\" title=\"Link to this heading\">#</a></h4>", "a[href=\"install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install sglang-plugin-FL<a class=\"headerlink\" href=\"#install-sglang-plugin-fl\" title=\"Link to this heading\">#</a></h1><h2>Runtime images and platform packages<a class=\"headerlink\" href=\"#runtime-images-and-platform-packages\" title=\"Link to this heading\">#</a></h2><p>Vendor-specific framework selection, runtime images, validation status, installation commands, and adaptation procedures are maintained on the centralized page: <a class=\"reference external\" href=\"https://flagos.io/resourcedownload?lang=en\">centralized vendor/framework/image-selection page</a>. Use that page to choose the vendor, framework, and image before installing or launching sglang-plugin-FL.</p><p>This page intentionally does not maintain a full image matrix or platform-specific package recipe.</p>", "a[href=\"quick-run-inference-task.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quick run an inference task<a class=\"headerlink\" href=\"#quick-run-an-inference-task\" title=\"Link to this heading\">#</a></h1><p>This section covers how to quick start a inference task through sglang-plugin-FL.</p>", "a[href=\"quick-run-inference-task.html#use-native-cuda-operators\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Use native CUDA operators<a class=\"headerlink\" href=\"#use-native-cuda-operators\" title=\"Link to this heading\">#</a></h2><p>To disable the plugin and use SGLang\u2019s original CUDA path:</p>", "a[href=\"requirements.html#verified-models\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Verified models<a class=\"headerlink\" href=\"#verified-models\" title=\"Link to this heading\">#</a></h2><p>Detailed model, quantization, platform, and validation status is maintained on the centralized page: <a class=\"reference external\" href=\"https://flagos.io/resourcedownload?lang=en\">centralized vendor/framework/image-selection page</a>. Do not treat this page as a complete vendor support matrix.</p>", "a[href=\"requirements.html#hardware-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware requirements<a class=\"headerlink\" href=\"#hardware-requirements\" title=\"Link to this heading\">#</a></h2>", "a[href=\"install.html#empty-mode\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Empty mode<a class=\"headerlink\" href=\"#empty-mode\" title=\"Link to this heading\">#</a></h2><p>Empty mode is an installation/runtime assembly mechanism for platforms where the CUDA-oriented SGLang dependency stack is not the target deployment environment. It avoids treating CUDA packages as the universal dependency set, but it is <strong>not</strong> a no-device mode.</p><p>The target platform still provides:</p>", "a[href=\"requirements.html#software-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Software requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2><p>The required runtime stack depends on the selected vendor, framework, and image. Use the centralized vendor/framework/image-selection page for platform-specific SDKs, framework builds, images, validation status, and package versions: <a class=\"reference external\" href=\"https://flagos.io/resourcedownload?lang=en\">centralized vendor/framework/image-selection page</a>.</p><p>Generic requirements for sglang-plugin-FL are:</p>", "a[href=\"requirements.html#empty-mode-boundary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Empty mode boundary<a class=\"headerlink\" href=\"#empty-mode-boundary\" title=\"Link to this heading\">#</a></h2><p>Empty mode is not a no-device mode. It changes installation/runtime assembly so that vendor-specific environments can provide their own runtime stack instead of inheriting a CUDA-oriented dependency set. The target platform still supplies vendor torch, drivers, firmware, device runtime, communication libraries, platform attention backend, and operators not covered by the plugin.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
